INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (10, 'okinawa-trip-2026-HuiYun', 8, '貨幣', '貨幣兌換與支付', '- 通用貨幣為日圓（JPY），建議出發前在台灣銀行或機場先換約 3-5 萬日圓現金應急。' || char(10) || '- 沖繩市區與大型商場普遍接受 Visa / Mastercard / JCB，但傳統市場、屋台、小餐館仍以現金為主。' || char(10) || '- 7-11、Lawson、FamilyMart 的 ATM 接受台灣金融卡跨國提款（需先開通海外提款功能）。' || char(10) || '- 匯率參考：1 TWD ≈ 4.5-5 JPY（依當下匯率而定）。', 1, 'general-tips', 0, '2026-05-28 15:15:08', '2026-05-28 15:15:08', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (11, 'okinawa-trip-2026-HuiYun', 9, '電器', '插頭與電壓', '- 日本插座為 A 型雙腳扁插，與台灣相容，多數電器可直接使用，不需轉接頭。' || char(10) || '- 電壓為 100V / 60Hz（台灣為 110V），多數 3C 產品（手機、相機、筆電變壓器）支援 100-240V 寬電壓可直接插。' || char(10) || '- 若攜帶吹風機、電熱毯等高功率電器，請先確認電壓相容性，建議直接使用旅館提供的設備。', 1, 'general-tips', 0, '2026-05-28 15:15:08', '2026-05-28 15:15:08', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (12, 'okinawa-trip-2026-HuiYun', 10, '簽證', '簽證與入境手續', '- 台灣護照前往日本免簽，最長停留 90 天。' || char(10) || '- 護照效期建議至少 6 個月以上，部分航空公司會要求至少有效至回程日後 1 個月。' || char(10) || '- 出發前 2 週於 Visit Japan Web（vjw-lp.digital.go.jp）線上登錄入境審查與海關申告，可大幅縮短抵達那霸機場的排隊時間。' || char(10) || '- 入境後請保留 QR code 截圖備查。', 1, 'general-tips', 0, '2026-05-28 15:15:08', '2026-05-28 15:15:08', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (13, 'okinawa-trip-2026-HuiYun', 11, '通訊', '通訊與網路', '- 推薦使用 eSIM（Airalo、Holafly、KKday）約 3-5 GB / 7 日 NT$300-500，落地掃 QR 即用。' || char(10) || '- 3 人以上同行可考慮租 Wi-Fi 分享器（台灣機場領取）較划算。' || char(10) || '- 沖繩本島市區與主要景點 4G/5G 訊號良好，離島部分區域訊號較弱。' || char(10) || '- 全家、7-11、星巴克、機場提供免費 Wi-Fi（需註冊）。', 1, 'general-tips', 0, '2026-05-28 15:15:08', '2026-05-28 15:15:08', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (14, 'okinawa-trip-2026-HuiYun', 12, '禮儀', '禮儀與文化注意', '- 入內脫鞋場合（旅館和室、神社、榻榻米餐廳）請依指示，襪子保持乾淨。' || char(10) || '- 大眾運輸內請勿大聲講電話，手機調靜音模式。' || char(10) || '- 垃圾分類嚴格，請依旅館或便利商店指示分可燃 / 不可燃 / 資源回收。' || char(10) || '- 沖繩有獨特琉球文化，造訪首里城、御嶽（聖地）時請保持安靜、勿擅入禁區。' || char(10) || '- 餐廳不收小費，結帳後鞠躬致謝即可。', 1, 'general-tips', 0, '2026-05-28 15:15:08', '2026-05-28 15:15:08', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (15, 'okinawa-trip-2026-HuiYun', 13, '治安', '治安與緊急聯絡', '- 沖繩治安整體良好，但仍須留意觀光區扒手與未掛牌計程車。' || char(10) || '- 緊急電話：警察 110、救護 / 火警 119。' || char(10) || '- 駐日台北經濟文化辦事處那霸分處：098-862-7008（24 小時急難救助專線：+81-80-8050-9076）。' || char(10) || '- 強烈建議投保涵蓋海外醫療、意外、行李遺失的旅遊保險，沖繩醫療費用偏高。', 1, 'general-tips', 0, '2026-05-28 15:15:09', '2026-05-28 15:15:09', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (16, 'okinawa-trip-2026-HuiYun', 14, '退稅', '退稅與購物', '- 外國旅客於貼有「Tax-Free」標示的商店單筆消費滿 5,000 日圓（未稅）即可申請退稅 10%。' || char(10) || '- 結帳時出示護照，店員直接扣稅或退現金，退稅商品需密封不可於日本境內拆封使用。' || char(10) || '- 沖繩 DFS Galleria、永旺夢樂城北谷、國際通電器藥妝店多支援。' || char(10) || '- 2026 年起免出示退稅商品給海關，流程更簡便。', 1, 'general-tips', 0, '2026-05-28 15:15:09', '2026-05-28 15:15:09', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (17, 'okinawa-trip-2026-HuiYun', 15, '氣候', '夏季氣候與颱風', '- 沖繩夏季（6-9 月）平均氣溫 28-32°C、濕度高，建議攜帶防曬乳（SPF50+）、太陽眼鏡、輕便雨衣。' || char(10) || '- 7-10 月為颱風季，出發前 3 天密切關注 JMA（jma.go.jp）颱風路徑預報。' || char(10) || '- 颱風來襲時航班、跨海大橋、船班停駛機率高，建議預留 1 天彈性緩衝。' || char(10) || '- 海水溫度 27-29°C 可從事浮潛、潛水、SUP，但須遵守海灘警戒旗號（紅旗禁泳）。', 1, 'general-tips', 0, '2026-05-28 15:15:09', '2026-05-28 15:15:09', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (18, 'okinawa-trip-2026-HuiYun', 16, '住宿在地', '沖繩那霸美居飯店 — 機場接駁與市區動線', '- 距那霸機場約 8 公里，車程 10-15 分鐘' || char(10) || '- 緊鄰單軌電車「壺川駅」，3 站可到縣廳前（國際通入口）' || char(10) || '- Day 1 深夜 22:07 抵達建議直接計程車入住（約 ¥1,500-2,000）' || char(10) || '- Day 5/6 連住期間白天行程後可搭單軌回飯店，省停車費也免酒駕風險', 1, 'lodging-tips', 0, '2026-05-28 16:10:42', '2026-05-28 16:10:42', 'ai', 'ai', NULL);
