INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (25, 'okinawa-trip-2026-HuiYun', 23, '住宿在地', '國際通周邊：那霸住宿首選', '此行程 7 晚有 5 晚以那霸為據點（首里城、國際通、牧志市場、波上宮），住宿建議選在國際通周邊。' || char(10) || '- 徒步可達餐飲、藥妝、伴手禮，親子覓食方便' || char(10) || '- 鄰近縣廳前、牧志單軌站，往返機場與市區皆便利' || char(10) || '- 巷弄內亦有安靜飯店，可避開主街夜間人聲', 1, 'lodging-tips', 0, '2026-05-28 22:50:21', '2026-05-28 22:50:21', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (26, 'okinawa-trip-2026-HuiYun', 24, '住宿在地', 'ゆいレール：親子移動最省力', '那霸市區移動首推 ゆいレール 單軌電車，從那霸機場直達市區約 30 分鐘。' || char(10) || '- 班次密集、站內有電梯與電扶梯，推車與行李上下輕鬆' || char(10) || '- 一日／二日券可無限搭乘，親子多趟移動更划算' || char(10) || '- 美麗海、萬座毛等北/中部景點則建議自駕或包車前往', 1, 'lodging-tips', 0, '2026-05-28 22:50:21', '2026-05-28 22:50:21', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (27, 'okinawa-trip-2026-HuiYun', 25, '住宿在地', '24h 便利店與藥妝補給', '那霸市區 FamilyMart、Lawson、7-11 密度高，多數飯店步行 3-5 分鐘內即有 24 小時超商。' || char(10) || '- 深夜可補水、嬰幼兒副食品、退熱貼等備品' || char(10) || '- 國際通沿線藥妝（大國藥妝、松本清）多營業到深夜' || char(10) || '- 部分超商設 ATM，可跨國提領日幣現金', 1, 'lodging-tips', 0, '2026-05-28 22:50:21', '2026-05-28 22:50:21', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (28, 'okinawa-trip-2026-HuiYun', 26, '住宿在地', '早餐選擇：在地早食推薦', '若飯店未含早餐，那霸市區早餐選擇多元。' || char(10) || '- 連鎖咖啡店與超商飯糰適合趕行程的早晨' || char(10) || '- 牧志公設市場周邊有沖繩そば與在地食堂，可體驗道地早食' || char(10) || '- 親子建議前一晚先於超商備好牛奶與麵包，避免早起久候', 1, 'lodging-tips', 0, '2026-05-28 22:50:21', '2026-05-28 22:50:21', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (29, 'okinawa-trip-2026-HuiYun', 27, '住宿在地', '行李寄存：退房後續玩無負擔', '沖繩飯店多數提供退房後行李暫存服務，可放心安排最後一日行程。' || char(10) || '- 單軌各站與那霸機場設有投幣式置物櫃（コインロッカー）' || char(10) || '- 退房日可寄物後再逛國際通、牧志市場，傍晚前往機場' || char(10) || '- 大型行李建議提前確認櫃位尺寸，旺季易滿', 1, 'lodging-tips', 0, '2026-05-28 22:50:21', '2026-05-28 22:50:21', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (30, 'okinawa-trip-2026-HuiYun', 28, '住宿在地', '親子住宿注意事項', '帶孩童入住沖繩飯店的幾項提醒：' || char(10) || '- 訂房時可備註嬰兒床、加大床或連通房需求' || char(10) || '- 夜間 22 點後走廊與大浴場多為安靜時段，留意孩童音量' || char(10) || '- 多數飯店禁帶外食至公共用餐區，房內食用較無虞' || char(10) || '- 確認是否附泡湯／大浴場，部分有兒童年齡或尿布限制', 1, 'lodging-tips', 0, '2026-05-28 22:50:21', '2026-05-28 22:50:21', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (31, 'okinawa-trip-2026-HuiYun', 29, '交通', '自駕與交通規則', '- 日本右駕左行，行人與車輛皆靠左，圓環、單行道請特別留意。' || char(10) || '- 6 歲以下兒童法規強制使用安全座椅，租車時務必一併預約。' || char(10) || '- 一般道路速限多為 40-60 km/h、高速公路 80 km/h，沿途測速嚴格。' || char(10) || '- 酒駕零容忍，前晚飲酒隔日仍可能殘留酒精，切勿駕駛。' || char(10) || '- 善用 ETC 與 MAPCODE 導航，沖繩多無號誌路口需放慢禮讓。', 1, 'general-tips', 0, '2026-05-28 23:00:12', '2026-05-28 23:00:12', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (32, 'okinawa-trip-2026-HuiYun', 30, '醫療', '醫療與常備藥準備', '- 台灣健保在日本不適用，看診與急診費用高昂，務必投保含海外醫療的旅遊險。' || char(10) || '- 自備慣用成藥（腸胃、止痛、暈車、過敏、OK 繃），日本成藥成分與台灣不同。' || char(10) || '- 處方藥請攜帶英文或日文診斷證明與藥袋，數量以行程所需為限。' || char(10) || '- 緊急傷病可撥 119 叫救護車，沖繩各市町村設有夜間急病診療所。', 1, 'general-tips', 0, '2026-05-28 23:00:12', '2026-05-28 23:00:12', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (33, 'okinawa-trip-2026-HuiYun', 31, '飲食', '飲水與飲食安全', '- 日本自來水可直接生飲，飯店與餐廳供水皆安全，便利商店亦有平價瓶裝水。' || char(10) || '- 食物過敏者請留意日文標示：卵（蛋）、乳、小麥、そば（蕎麥）、落花生（花生）。' || char(10) || '- 沖繩夏季氣溫高，生食海鮮與熟食請盡快食用、避免久放。' || char(10) || '- 餐廳多提供免費冰水（お冷）與濕紙巾，兒童餐具可主動向店員索取。', 1, 'general-tips', 0, '2026-05-28 23:00:12', '2026-05-28 23:00:12', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (34, 'okinawa-trip-2026-HuiYun', 32, '親子', '親子備品與設施', '- 尿布、副食品、退熱貼在當地藥妝與超市皆可購得，不需大量攜帶。' || char(10) || '- AEON、大型商場與那霸機場設有哺乳室與尿布台，親子設施完善。' || char(10) || '- 多數景點 6 歲以下免費、國中小有兒童票，記得帶證件備查。' || char(10) || '- 推車可帶，單軌與商場皆有電梯；自然步道與沙灘建議改用揹巾。', 1, 'general-tips', 0, '2026-05-28 23:00:12', '2026-05-28 23:00:12', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (35, 'okinawa-trip-2026-HuiYun', 33, '安全', '海上活動與海灘安全', '- 浮潛、SUP、青之洞窟請選有保險與救生員的合格業者，全程穿著救生衣。' || char(10) || '- 注意海灘旗號：紅旗禁止下水、黃旗小心、藍綠旗較安全。' || char(10) || '- 沖繩夏季有水母與離岸流，請於泳區範圍內活動，勿單獨遠泳。' || char(10) || '- 防曬建議選珊瑚友善（reef-safe）款，並備防水袋保護手機與證件。', 1, 'general-tips', 0, '2026-05-28 23:00:12', '2026-05-28 23:00:12', 'ai', 'ai', NULL);
INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (36, 'okinawa-trip-2026-HuiYun', 34, '應變', '防災與實用 APP', '- 必備：Google 翻譯（下載離線日文包）、Google Maps 離線地圖、NAVITIME 交通。' || char(10) || '- 防災下載日本氣象廳「JMA」與觀光廳「Safety tips」APP，颱風地震即時警報（支援中文）。' || char(10) || '- 護照、保險單、訂房確認、緊急聯絡拍照存雲端並做離線備份。' || char(10) || '- 急難救助：駐那霸台北經濟文化辦事處 24h 專線 +81-80-8050-9076。', 1, 'general-tips', 0, '2026-05-28 23:00:12', '2026-05-28 23:00:12', 'ai', 'ai', NULL);
