INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (64, 'okinawa-trip-2026-HuiYun', 58, '行程建議', '**多個餐廳 category 標記錯誤**：約 10+ 間餐廳分類有誤，例如：Day 3 ラーメン暖暮→甜點（應為拉麵）、琉球の牛→海鮮（應為燒肉）；Day 4 焼肉てるりん→甜點（應為燒肉）、ラーメン太陽→海鮮（應為拉麵）；Day 5 一蘭拉麵→海鮮（應為拉麵）、A&W→甜點（應為美式速食）、焼肉もとぶ牧場→甜點（應為燒肉）。分類影響篩選與顯示圖示', '', 1, 'general-tips', 0, '2026-04-22 17:20:38', '2026-04-22 17:20:38', 'ai', 'ai', 'legacy-docs:suggestions:527');
