INSERT INTO "trip_pretrip_notes" ("id", "trip_id", "sort_order", "section", "title", "content", "ai_generated", "ai_source", "version", "created_at", "updated_at", "origin", "managed_by", "semantic_key") VALUES (66, 'okinawa-trip-2026-HuiYun', 60, '行程建議', '**Day 6 還車動線可優化**：目前是 晚餐（壺川附近）→ 開車去新都心還車 → 搭電車回壺川。可考慮先還車 → 在新都心/おもろまち附近吃晚餐 → 搭電車回壺川飯店，動線更順暢', '', 1, 'general-tips', 0, '2026-04-22 17:20:38', '2026-04-22 17:20:38', 'ai', 'ai', 'legacy-docs:suggestions:529');
