INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (759, 86, 10, '先到**タウンプラザかねひで 壺川店**採買（飯店旁步行3分鐘，09:00~23:00），再回飯店整理行李', 'ai', '2026-06-14 09:43:14', 0, '20:50', NULL, 0, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (761, 87, 1, '沖繩人的廚房！1樓鮮魚海產攤位選購食材，2樓代客料理（3樣500日圓）；必吃夜光貝、石垣牛握壽司、步沙翁（約1.5小時）', 'ai', '2026-06-29T04:01:27.515Z', 0, '09:07', '10:37', 9, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (764, 87, 2, '全長5公里鐘乳石洞穴（開放800m，步行約40分鐘）；必看百萬支石筍燈光造景、王國村琉球工藝體驗、SUPER EISA太鼓秀（10:30/12:30/14:30）', 'ai', '2026-05-18 12:28:58', 0, '13:22', '14:22', 1, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (765, 87, 5, '沖繩八社之首，崖上絕美神社；必看紅型圖案御守（800~1200日圓）、貝殼良緣御守、波之上海灘絕景拍照點（後方臨港道路）', 'ai', '2026-05-18 12:28:58', 0, '14:52', '15:22', 0, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (766, 87, 4, '沖繩小希臘白色露台商場；必吃幸福鬆餅（建議提前2週訂位）、氾濫漢堡、47Store冰淇淋；必看子寶岩打卡點、夕陽海景、飛機起降（約2小時）', 'ai', '2026-05-18 12:28:58', 0, '15:37', '17:37', 0, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (767, 87, 6, '還車前加滿油。瀨長島往那霸方向的國道 331 沿線有多間加油站，自助式（セルフ）較便宜。**加油步驟**：停車熄火 → 選油種（レギュラー）→ 插入信用卡或投入現金 → 拿油槍加油 → 取收據', 'ai', '2026-05-18 12:28:58', 0, '17:47', '18:02', 0, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (768, 87, 8, '那霸美居飯店（壺川）附近的晚餐推薦，開車約5~10分鐘即達，最後一晚享受沖繩美食', 'ai', '2026-05-18 12:28:58', 0, '18:17', '19:17', 3, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (772, 85, 4, NULL, 'ai', '2026-06-14 09:39:24', 0, '13:30', '15:00', 11, 2);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (773, 85, 3, '沖縄美ら海水族館 — 入場後先預約 Ocean Blue Cafe，13:00 看海豚秀（從水族館出口徒步約5分鐘，遊園車於「3.海豚劇場」下車），再返回館內參觀，15:00 看黑潮之海餵食秀。【黑潮之海】9:30（鬼蝠魟攝食）／15:00・17:00（鯨鯊垂直站立餵食）【海豚秀】10:30／11:30／13:00／15:00／17:00', 'ai', '2026-06-14 09:39:24', 0, '08:02', '13:00', 0, 8);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (774, 85, 5, 'THE Sinmay — 今帰仁村人氣小木屋咖啡站，招牌現刨生黑糖拿鐵，店員現場刨黑糖灑在拿鐵上超療癒（約30分鐘）', 'ai', '2026-06-14 09:39:24', 0, '15:38', '16:08', 2, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (775, 85, 6, '古宇利オーシャンタワー — 觀景塔、眺望古宇利大橋（約30分鐘）', 'ai', '2026-06-14 09:39:24', 0, '16:33', '17:03', 0, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (776, 85, 7, '古宇利島 — 環島兜風、沙灘散步（約2小時）', 'ai', '2026-06-14 09:39:24', 0, '17:06', '19:06', 0, 0);
INSERT INTO "trip_entries" ("id", "day_id", "sort_order", "description", "source", "updated_at", "order_in_day", "start_time", "end_time", "entry_pois_version", "version") VALUES (777, 85, 8, NULL, 'ai', '2026-06-14 09:39:24', 0, '19:35', '20:35', 8, 0);
