INSERT INTO "trip_entry_pois" ("id", "entry_id", "poi_id", "sort_order", "added_at", "updated_at", "description", "note", "reservation", "reservation_url") VALUES (4, 418, 486, 1, '2026-04-22 17:19:27', '2026-06-02 10:33:50', NULL, '樂桃在 LCC 航廈，建議起飛前 2 小時到機場辦理登機。機場還能買到：⑥Royce鹽巧克力洋芋片⭐5、⑧砂糖樹夾心餅乾⭐4.5、⑨南風堂辣味蝦餅⭐5' || char(10) || char(10) || '🛍️ **國內線航站樓（2F、3F）是最後的購物天堂** — 甚至有很多市中心買不到的限定商品' || char(10) || char(10) || '⏰ **早點到機場**：國內線和國際線連通（透過 2F、3F 的 Yui-Nichi St.），國內線店鋪遠比國際線豐富。飛國際航班建議先去國內線逛足了，再走過去國際線辦登機' || char(10) || char(10) || '💰 **免稅疊加**：雖然是國內線，但有些店鋪（如 DFS 免稅店特定區域）針對從沖繩離境的遊客也有稅費優惠或特定折扣，可留意櫃台提示' || char(10) || char(10) || '提前整理好免稅單據與商品，人多時排隊需 30 分鐘以上', NULL, NULL);
