INSERT INTO "trip_entry_pois" ("id", "entry_id", "poi_id", "sort_order", "added_at", "updated_at", "description", "note", "reservation", "reservation_url") VALUES (349, 772, 446, 4, '2026-05-13 00:19:16', '2026-06-08T22:17:24.681Z', '沖繩人氣漢堡名店，連續 15 年獲選冠軍。招牌**スパーキーバーガー**高達 20cm，手打牛肉排搭配特製醬汁，配炸薯條與根啤酒 Root Beer 是經典組合', '超人氣常排隊，建議提早到。前往水族館順路' || char(10) || '不需訂位', NULL, NULL);
INSERT INTO "trip_entry_pois" ("id", "entry_id", "poi_id", "sort_order", "added_at", "updated_at", "description", "note", "reservation", "reservation_url") VALUES (350, 772, 427, 5, '2026-05-13 00:19:16', '2026-06-08T22:17:24.681Z', 'ピザ喫茶 花人逢 — 本部町山頂古民家披薩咖啡廳，1998 年開業。手工窯烤披薩搭配無敵海景，可眺望伊江島、瀨底島，被譽為沖繩最美景觀餐廳之一', '不接受預約，到場登記候位。週二三公休。景色一流適合放鬆' || char(10) || '不需訂位', NULL, NULL);
INSERT INTO "trip_entry_pois" ("id", "entry_id", "poi_id", "sort_order", "added_at", "updated_at", "description", "note", "reservation", "reservation_url") VALUES (352, 774, 447, 1, '2026-05-13 00:19:16', '2026-06-02 10:33:50', '今帰仁半島丘上景觀咖啡，鬆餅 + 黑糖咖啡，頂樓展望台可眺望古宇利方向海景', 'Shinmei Coffee 備案。月・木 公休，11:00–18:00，現金 only，附停車場' || char(10) || '10:00~16:30 營業，僅收現金或電子支付（不收信用卡）；附免費停車場', NULL, NULL);
