INSERT INTO "trip_health_reports" ("trip_id", "user_id", "status", "request_id", "findings_json", "error_message", "created_at", "completed_at") VALUES ('okinawa-trip-2026-Ray', 'ce218869-cec3-4a84-b565-3f72cf1642d0', 'completed', 244, '[{"severity":"medium","title":"Day5 報到後離場用餐","description":"第 5 天 17:15 已在那霸機場報到託運行李，18:00 卻到記錄距離約 8 公里外的牛排屋88用餐再折返趕 20:55 班機，與「機場航廈內用餐」的描述不符。","dimension":"timing","suggestion":"晚餐改到報到前，或換成機場航廈內的餐廳。","action_target":{"day":5,"entry_id":453}},{"severity":"medium","title":"Day5 移動仍標開車","description":"租車已於第 4 天在 T Galleria 還車，但第 5 天首里城、國際通、機場等段的移動仍標示為開車，實際應改搭單軌電車或計程車。","dimension":"distance","suggestion":"確認第 5 天交通方式並更新移動記錄。","action_target":{"day":5}},{"severity":"low","title":"Day2 標題有瀨底卻未排","description":"第 2 天標題為「浮潛・瀨底」、行程簡介也提到瀨底海灘，但當天實際為青之洞窟、萬座毛、道之驛站許田，並未安排瀨底海灘。","dimension":"sights","suggestion":"補排瀨底海灘，或修正當天標題以免落差。","action_target":{"day":2}},{"severity":"low","title":"Day4 午晚餐間隔偏長","description":"第 4 天午餐 A&W 在 12:00、晚餐 19:30，中間約 7.5 小時只在來客夢逛街，下午容易肚子餓。","dimension":"meals","suggestion":"下午在來客夢補一份點心，或把晚餐略微提前。","action_target":{"day":4,"entry_id":443}},{"severity":"low","title":"萬座毛等景點缺評分","description":"第 2 天萬座毛、道之驛站許田未填評分，第 4 天伊芸休息站評分僅 3.8。萬座毛是沖繩知名海景，建議補上評分供參考。","dimension":"sights","suggestion":"補齊萬座毛與許田的評分資訊。","action_target":{"day":2,"entry_id":1157}}]', NULL, '2026-07-09 15:11:39', '2026-07-09 16:37:06');
